/**
 * Arithmetic in GF(256) as QR uses it: the field generated by the primitive
 * polynomial x^8 + x^4 + x^3 + x^2 + 1 (0x11D) with α = 2 as generator.
 *
 * Log and antilog tables are built once at module init. Everything downstream
 * is a table lookup, which is what keeps encode() inside the 8 ms budget.
 */

export const PRIMITIVE = 0x11d;
export const ORDER = 256;

const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);

(function buildTables() {
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= PRIMITIVE;
  }
  // Duplicate the cycle so mul() can index without a modulo.
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
})();

/** α^n, for any non-negative n. */
export function exp(n: number): number {
  return EXP[n % 255];
}

/** The exponent e such that α^e === n. Undefined for n === 0. */
export function log(n: number): number {
  if (n === 0) throw new Error('log(0) is undefined in GF(256)');
  return LOG[n];
}

export function add(a: number, b: number): number {
  return a ^ b;
}

export const sub = add;

export function mul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0;
  return EXP[LOG[a] + LOG[b]];
}

export function div(a: number, b: number): number {
  if (b === 0) throw new Error('division by zero in GF(256)');
  if (a === 0) return 0;
  return EXP[LOG[a] + 255 - LOG[b]];
}

export function inv(a: number): number {
  if (a === 0) throw new Error('0 has no inverse in GF(256)');
  return EXP[255 - LOG[a]];
}

export function pow(a: number, n: number): number {
  if (a === 0) return n === 0 ? 1 : 0;
  return EXP[(LOG[a] * n) % 255];
}

/*
 * Polynomials are Uint8Array, highest-degree coefficient first — the order the
 * QR spec writes them in, and the order the long-division view renders.
 */

export function polyMul(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length + b.length - 1);
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    if (ai === 0) continue;
    const la = LOG[ai];
    for (let j = 0; j < b.length; j++) {
      const bj = b[j];
      if (bj === 0) continue;
      out[i + j] ^= EXP[la + LOG[bj]];
    }
  }
  return out;
}

export function polyAdd(a: Uint8Array, b: Uint8Array): Uint8Array {
  const len = Math.max(a.length, b.length);
  const out = new Uint8Array(len);
  out.set(a, len - a.length);
  for (let i = 0; i < b.length; i++) out[len - b.length + i] ^= b[i];
  return out;
}

/** Multiply every coefficient by a scalar. */
export function polyScale(a: Uint8Array, s: number): Uint8Array {
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = mul(a[i], s);
  return out;
}

/** Horner evaluation of p at x. */
export function polyEval(p: Uint8Array, x: number): number {
  let y = p[0];
  for (let i = 1; i < p.length; i++) y = mul(y, x) ^ p[i];
  return y;
}

/** Drop leading zero coefficients. An all-zero polynomial becomes [0]. */
export function polyTrim(p: Uint8Array): Uint8Array {
  let i = 0;
  while (i < p.length - 1 && p[i] === 0) i++;
  return p.slice(i);
}

/** Formal derivative. Over GF(2^m), even-index terms vanish. */
export function polyDerivative(p: Uint8Array): Uint8Array {
  const degree = p.length - 1;
  if (degree === 0) return new Uint8Array([0]);
  const out = new Uint8Array(degree);
  for (let i = 0; i < degree; i++) {
    const power = degree - i;
    out[i] = power & 1 ? p[i] : 0;
  }
  return polyTrim(out);
}
